<?php
$root='C:\\laragon\\www\\wilcatsystems_papachito';$e=[];foreach(file($root.'/.env',FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES) as $l){if(strpos($l,'=')===false)continue;[$k,$v]=explode('=',$l,2);$e[trim($k)]=trim(trim($v),"'\"");}$p=new PDO("mysql:host={$e['DB_HOST']};port={$e['DB_PORT']};dbname={$e['DB_DATABASE']};charset=utf8mb4",$e['DB_USERNAME'],$e['DB_PASSWORD']);foreach(['categorias','producto_stock','cpe_cabecera','cpe_detalle','venta_medio_pago','mobile_sales','mobile_audit'] as $t){echo "[$t] ";try{$n=$p->query("SELECT COUNT(*) FROM `$t`")->fetchColumn();echo "rows=$n\n";foreach($p->query("DESCRIBE `$t`") as $r)echo $r['Field']." ";echo "\n";}catch(Throwable $x){echo $x->getMessage()."\n";}}echo "[stock warehouses]\n";foreach($p->query('SELECT id_almacen, id_empresa_negocio, COUNT(*) n FROM producto_stock GROUP BY id_almacen,id_empresa_negocio ORDER BY n DESC') as $r)echo implode(',', $r)."\n";
